hooks.command:
: prawduct-unloaded-tripwire
m="${CLAUDE_CONFIG_DIR:-$HOME/.claude}/plugins/installed_plugins.json"
if command -v python3 >/dev/null 2>&1; then
v=$(python3 -c 'import json,os,sys
f=os.path.expanduser(sys.argv[1]);p=os.path.realpath(sys.argv[2])
def out(v):
 print(v);sys.exit(0)
def rd(x):
 try:return open(x).read().strip()
 except (IOError,OSError,ValueError):return ""
P=[p]
g=rd(os.path.join(p,".git"))
if g.startswith("gitdir:"):
 x=os.path.join(p,g[7:].strip());c=rd(os.path.join(x,"commondir"))
 c=os.path.realpath(os.path.join(x,c)) if c else ""
 if os.path.basename(c)==".git":P.append(os.path.dirname(c))
try:
 m=json.load(open(f))
except (IOError,OSError):
 out("unreadable" if os.path.exists(f) else "missing")
except ValueError:
 out("unreadable")
d=m.get("plugins") if isinstance(m,dict) else None
if not isinstance(d,dict):
 out("unreadable")
r=d.get("prawduct@prawduct")
if r is None:
 out("inactive")
if not isinstance(r,list):
 out("unreadable")
b=0
for x in r:
 if not isinstance(x,dict):
  b=1;continue
 if x.get("scope") in ("user","global"):
  out("active")
 q=x.get("projectPath")
 if not isinstance(q,str):
  b=1;continue
 if os.path.realpath(os.path.expanduser(q)) in P:
  out("active")
out("unreadable" if b else "inactive")' "$m" "${CLAUDE_PROJECT_DIR:-.}" 2>/dev/null) || v="python3 exited $?, so the check did not finish"
else v="python3 not found"; fi
case "$v" in
active) ;;
inactive) echo "PRAWDUCT GOVERNANCE IS NOT ACTIVE IN THIS SESSION. This repo is governed by Prawduct, but prawduct@prawduct is not installed for it in this Claude Code profile ($m): no session banner, no /prawduct:* skills, no Stop gates. Tell the user before any work, and do not imitate the gates by reading the plugin's files. Fix: run claude plugin install prawduct@prawduct in this repo, then restart the session. (Loaded the plugin with --plugin-dir? Then ignore this line.)" ;;
*) echo "PRAWDUCT: could not verify that prawduct@prawduct is installed for this repo ($v: $m). If no Prawduct session banner appeared at session start, governance is not loaded: tell the user before any work, and do not imitate its gates by reading the plugin's files." ;;
esac
exit 0
